mapper.select:
select comment.*, type.name as typeName, hotel.name as hotelName, user.name as userName
from comment
left join type on comment.type_id = type.id and type.deleted = 0
left join hotel on comment.hotel_id = hotel.id and hotel.deleted = 0
left join user on comment.user_id = user.id and user.deleted = 0

    comment.deleted=0
     and comment.id = #{id}
     and comment.content like concat('%', #{content}, '%')
     and comment.time = #{time}
     and comment.type_id = #{typeId}
     and comment.hotel_id = #{hotelId}
     and comment.user_id = #{userId}
     and comment.parent_id = #{parentId}
     and comment.role = #{role}


order by comment.id desc

